using SaySo.Mac.Interop;

namespace SaySo.Mac.Platform;

/// <summary>
/// Общий буфер обмена macOS (NSPasteboard). Текст SaySo помечается типами nspasteboard.org «Transient» и «AutoGenerated»:
/// менеджеры истории буфера (Maccy, Paste, Raycast и т. п.) такие записи не сохраняют (аналог исключения из Win+V).
/// </summary>
internal static class Pasteboard
{
    private const string TextType = "public.utf8-plain-text";
    private const string TransientType = "org.nspasteboard.TransientType";
    private const string AutoGeneratedType = "org.nspasteboard.AutoGeneratedType";

    private static nint General => ObjC.Send(ObjC.Class("NSPasteboard"), ObjC.Sel("generalPasteboard"));

    /// <summary>Счётчик изменений буфера: по нему видно, что буфер после нас никто не трогал.</summary>
    public static long ChangeCount => ObjC.SendLong(General, ObjC.Sel("changeCount"));

    /// <summary>Записать текст. <paramref name="transient"/> — не для истории буфера (служебная вставка и восстановление).</summary>
    public static bool SetText(string text, bool transient)
    {
        using var pool = AutoreleasePool.Push();
        var item = NewItem();
        if (!ObjC.SendBool(item, ObjC.Sel("setString:forType:"), ObjC.Str(text), ObjC.Str(TextType)))
        {
            return false;
        }

        if (transient)
        {
            MarkTransient(item);
        }

        return Write([item]);
    }

    /// <summary>Снимок всего содержимого буфера (все элементы и типы: текст, картинки, файлы), чтобы вернуть его после вставки.</summary>
    public static Snapshot Save()
    {
        using var pool = AutoreleasePool.Push();
        var items = new List<List<(string Type, nint Data)>>();
        var pbItems = ObjC.Send(General, ObjC.Sel("pasteboardItems"));
        for (long i = 0; i < NS.Count(pbItems); i++)
        {
            var item = NS.At(pbItems, i);
            var types = ObjC.Send(item, ObjC.Sel("types"));
            var saved = new List<(string, nint)>();
            for (long t = 0; t < NS.Count(types); t++)
            {
                var type = NS.At(types, t);
                var data = ObjC.Send(item, ObjC.Sel("dataForType:"), type);
                if (data != 0 && ObjC.ToStr(type) is { } name)
                {
                    saved.Add((name, ObjC.Retain(data)));
                }
            }

            if (saved.Count > 0)
            {
                items.Add(saved);
            }
        }

        return new Snapshot(items);
    }

    private static nint NewItem() => ObjC.Send(ObjC.New("NSPasteboardItem"), ObjC.Sel("autorelease"));

    /// <summary>Пометки nspasteboard.org добавляются к первому элементу: менеджеры буфера смотрят на типы элементов.</summary>
    private static void MarkTransient(nint item)
    {
        var empty = ObjC.Send(ObjC.Class("NSData"), ObjC.Sel("data"));
        ObjC.SendBool(item, ObjC.Sel("setData:forType:"), empty, ObjC.Str(TransientType));
        ObjC.SendBool(item, ObjC.Sel("setData:forType:"), empty, ObjC.Str(AutoGeneratedType));
    }

    private static bool Write(nint[] items)
    {
        var pb = General;
        ObjC.SendLong(pb, ObjC.Sel("clearContents"));
        return ObjC.SendBool(pb, ObjC.Sel("writeObjects:"), NS.Array(items));
    }

    /// <summary>Содержимое буфера на момент <see cref="Save"/>; данные удерживаются до <see cref="Dispose"/>.</summary>
    internal sealed class Snapshot(List<List<(string Type, nint Data)>> items) : IDisposable
    {
        public bool IsEmpty => items.Count == 0;

        /// <summary>Вернуть содержимое (помеченным как служебное: в истории буфера оно уже есть).</summary>
        public bool Restore()
        {
            if (IsEmpty)
            {
                return true;
            }

            using var pool = AutoreleasePool.Push();
            var objects = new List<nint>();
            foreach (var item in items)
            {
                var pbItem = NewItem();
                foreach (var (type, data) in item)
                {
                    ObjC.SendBool(pbItem, ObjC.Sel("setData:forType:"), data, ObjC.Str(type));
                }

                objects.Add(pbItem);
            }

            if (!items[0].Any(t => t.Type == TransientType))
            {
                MarkTransient(objects[0]);
            }

            return Write([.. objects]);
        }

        public void Dispose()
        {
            foreach (var item in items)
            {
                foreach (var (_, data) in item)
                {
                    ObjC.Release(data);
                }
            }

            items.Clear();
        }
    }
}
